from PyQt6.QtWidgets import QWidget,QVBoxLayout,QLabel,QPlainTextEdit,QLineEdit,QPushButton,QFormLayout
class IntegrationsSettings(QWidget):
 def __init__(self,c,save,firebase):
  super().__init__();self.save=save;self.firebase=firebase;l=QVBoxLayout(self);l.addWidget(QLabel('Firebase synchronization'));l.addWidget(QLabel('Firebase is optional. It synchronizes alarm acknowledgement and cooldown state with your Android device. Credentials stay in local config.',styleSheet='color:#00A8FF'));f=QFormLayout();self.url=QLineEdit(c['firebase']['database_url']);self.json=QPlainTextEdit(c['firebase']['service_account_json']);self.json.setPlaceholderText('Paste Firebase service-account JSON');f.addRow('Database URL',self.url);f.addRow('Service-account JSON',self.json);l.addLayout(f);b=QPushButton('Save and test Firebase');b.clicked.connect(self.commit);l.addWidget(b);self.result=QLabel('Not tested');l.addWidget(self.result);l.addStretch()
 def commit(self):
  self.save('firebase',{'database_url':self.url.text().strip(),'service_account_json':self.json.toPlainText().strip()}); self.firebase.config['firebase']={'database_url':self.url.text().strip(),'service_account_json':self.json.toPlainText().strip()};self.result.setText('Connected ✓' if self.firebase.connect() else 'Connection failed — check the URL, JSON, and database rules.')
